def line_total(price, quantity):
    subtotal = price * quantity
    if quantity >= 10:
        subtotal = subtotal * 0.9
    else:
        subtotal = subtotal * 0.98
    if subtotal < 0:
        return 0
    return subtotal

def delivery_fee(total):
    if total >= 100:
        return 0
    if total >= 50:
        return 5
    return 10

def available_count(stock):
    count = 0
    for amount in stock:
        if amount <= 0:
            continue
        count = count + amount
    return count

def can_fulfill(stock, requested):
    remaining = requested
    for amount in stock:
        remaining = remaining - amount
        if remaining <= 0:
            return True
    return False

from pricing import line_total, delivery_fee

def order_total(items):
    total = 0
    for price, quantity in items:
        if quantity <= 0:
            continue
        total = total + line_total(price, quantity)
    return total + delivery_fee(total)

def item_count(items):
    count = 0
    for price, quantity in items:
        if quantity > 0:
            count = count + quantity
    return count

from inventory import can_fulfill, available_count
from reporting import summary, print_reports

def process_order(items, stock, requested):
    if not can_fulfill(stock, requested):
        return "Insufficient stock"
    available = available_count(stock)
    message = summary(items)
    return f"{message}; stock: {available}"

def process_batches(batches, limit):
    selected = []
    for items in batches:
        if len(selected) >= limit:
            break
        selected.append(items)
    return print_reports(selected)
